# FBV vs CBV: both are callables; as_view() returns a function that builds a fresh instance
class View:
    @classmethod
    def as_view(cls):
        def view(request):
            self = cls()                       # new instance per request: self state is safe
            handler = getattr(self, request["method"].lower(), None)
            if handler is None:
                return "405 Method Not Allowed"
            return handler(request)            # dispatch by HTTP method
        return view

class Counter(View):
    def __init__(self):
        self.calls = 0
    def get(self, request):
        self.calls += 1
        return "GET ok, calls on this instance = %d" % self.calls

def fbv(request):                              # function-based: explicit and simple
    return "FBV handled " + request["method"]

cbv = Counter.as_view()
print("FBV :", fbv({"method": "GET"}))
print("CBV :", cbv({"method": "GET"}))
print("CBV :", cbv({"method": "GET"}))         # still 1: fresh instance each time
print("CBV :", cbv({"method": "POST"}))
print("type of as_view():", type(cbv).__name__)

# Lazy QuerySet model: chaining builds a query, evaluation runs it once and caches
DB = [{"id": i, "price": i * 10} for i in range(1, 6)]
queries = []

class QuerySet:
    def __init__(self, conds=()):
        self.conds = conds
        self._result_cache = None
    def filter(self, f, label):
        return QuerySet(self.conds + ((f, label),))   # new QuerySet, no SQL yet
    def _fetch(self):
        if self._result_cache is None:
            queries.append("WHERE " + " AND ".join(l for _, l in self.conds))
            self._result_cache = [r for r in DB if all(f(r) for f, _ in self.conds)]
        return self._result_cache
    def __iter__(self):
        return iter(self._fetch())
    def __bool__(self):
        return bool(self._fetch())
    def exists(self):
        queries.append("SELECT 1 ... LIMIT 1 (exists)")
        return any(all(f(r) for f, _ in self.conds) for r in DB)

qs = QuerySet().filter(lambda r: r["price"] > 10, "price>10")
qs2 = qs.filter(lambda r: r["price"] < 50, "price<50")
print("after building:", len(queries), "queries")
print("rows:", [r["id"] for r in qs2])
print("rows again:", [r["id"] for r in qs2])   # served from cache
print("after 2 iterations:", len(queries), "query:", queries)
print("derived qs hits db again:", [r["id"] for r in qs.filter(lambda r: True, "all")])
print("total queries:", len(queries))

# Migration plan: topological sort of unapplied nodes, and detecting merge conflicts (many leaves)
graph = {                       # migration -> its dependencies
    "0001_initial": [],
    "0002_add_email": ["0001_initial"],
    "0003_add_phone": ["0001_initial"],      # parallel branch
    "0004_backfill": ["0002_add_email"],
}
applied = {"0001_initial"}                    # recorded in django_migrations

def plan(graph, applied):
    done, order = set(applied), []
    def visit(n):
        if n in done: return
        for dep in graph[n]:
            visit(dep)                        # dependencies first
        done.add(n); order.append(n)
    for n in sorted(graph):
        visit(n)
    return order

def leaves(graph):
    used = {d for deps in graph.values() for d in deps}
    return sorted(n for n in graph if n not in used)

print("graph  :", graph)
print("applied:", sorted(applied))
print("plan   :", plan(graph, applied))
print("leaves :", leaves(graph))
if len(leaves(graph)) > 1:
    print("conflict: multiple leaf nodes -> makemigrations --merge")

# How Django builds the middleware chain: iterate the list in reverse, wrap each layer
def convert_exception_to_response(get_response):
    def inner(request):
        try:
            return get_response(request)
        except KeyError:
            return "404"                     # exception becomes a response at each layer
    return inner

def timing(get_response):
    def mw(request):
        request["trace"].append("timing: before")
        resp = get_response(request)
        request["trace"].append("timing: after")
        return resp
    return mw

def blocker(get_response):
    def mw(request):
        if request.get("blocked"):
            request["trace"].append("blocker: short-circuit")
            return "403"                     # view and inner layers never run
        return get_response(request)
    return mw

def view(request):
    request["trace"].append("view")
    return "200 " + request["data"]["x"]     # KeyError when missing

MIDDLEWARE = [timing, blocker]               # first = outermost
handler = convert_exception_to_response(view)
for factory in reversed(MIDDLEWARE):         # reverse: last listed is wrapped first
    handler = convert_exception_to_response(factory(handler))

for req in [{"data": {"x": "ok"}}, {"data": {}}, {"data": {}, "blocked": True}]:
    req["trace"] = []
    print(handler(req), "|", ", ".join(req["trace"]))

# DRF-style validation order: field checks, validate_<field>, then validate(attrs)
class ValidationError(Exception):
    def __init__(self, errors): self.errors = errors

FIELDS = {"age": int, "name": str, "password": str}
def validate_name(v):
    if v != v.strip(): raise ValueError("no spaces around name")
    return v
def validate(attrs):
    if attrs["password"] == attrs["name"]:
        raise ValueError("password must differ from name")
    return attrs

def is_valid(data, partial=False):
    errors, attrs = {}, {}
    for field, typ in FIELDS.items():                  # declaration order
        if field not in data:
            if not partial: errors[field] = "required"
            continue
        try:
            value = typ(data[field])                   # to_internal_value: "36" -> 36
            if field == "name": value = validate_name(value)
            attrs[field] = value
        except ValueError as e:
            errors[field] = str(e)                     # collect, do not stop at first
    if errors:
        return None, errors                            # object-level checks are skipped
    try:
        return validate(attrs), {}
    except ValueError as e:
        return None, {"non_field_errors": str(e)}

for data in [{"age": "36", "name": "ann", "password": "x1"},
             {"age": "abc", "name": " bo"},
             {"age": "20", "name": "cy", "password": "cy"}]:
    print(data, "->", is_valid(data))

# DRF permission flow: authenticate, has_permission, object check, 401 vs 403
class NotAuth(Exception): pass
class Denied(Exception): pass

class IsOwnerOrReadOnly:
    def has_permission(self, req, obj=None): return True
    def has_object_permission(self, req, obj):
        return req["method"] in ("GET", "HEAD") or obj["owner"] == req["user"]

def authenticate(req, www_authenticate):
    return req["user"], www_authenticate

def check(req, obj, www_authenticate):
    user, hdr = authenticate(req, www_authenticate)
    perm = IsOwnerOrReadOnly()
    if not perm.has_permission(req):
        deny(user, hdr)
    if obj is not None and not perm.has_object_permission(req, obj):   # only via get_object()
        deny(user, hdr)
    return "200"

def deny(user, hdr):
    if user is None:                      # nobody logged in
        raise NotAuth("401" if hdr else "403")   # 401 only with a WWW-Authenticate header
    raise Denied("403")

note = {"owner": "ann"}
cases = [("ann", "PUT", True), ("bo", "PUT", True), ("bo", "GET", True),
         (None, "PUT", True), (None, "PUT", False)]
for user, method, hdr in cases:
    req = {"user": user, "method": method}
    try:
        out = check(req, note, hdr)
    except (NotAuth, Denied) as e:
        out = str(e)
    print("user=%-4s %-3s www_auth=%-5s -> %s" % (user, method, hdr, out))
